-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'TESTES DE FRONTEND' and a.numero = 3
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 3 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 03', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 03 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/TESTES-DE-FRONTEND/ATIVIDADES/ATIVIDADE-PRATICA-AULA-03.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique o que é um teste automatizado.', 0.2, 'Teste automatizado é um **programa que testa outro programa**: prepara os dados, executa o código e **compara o resultado com o esperado**, automaticamente.', 'Palavras-chave: programa que testa programa; executa; compara com o esperado. Nota cheia (0,2): definição completa. Metade (0,1): "teste feito pelo computador" sem a comparação. Zero (0): teste manual.'),
      (v_atividade, 1, 2, 'Explique o que é um teste unitário, o que ele não usa (banco, rede, navegador) e por que fica na base da pirâmide.', 0.4, 'O teste unitário verifica a **menor parte do código isoladamente** (uma função ou módulo), **sem banco, sem rede e sem navegador**. Fica na **base da pirâmide** porque é **rápido e barato**: dá para ter **muitos** e rodá-los a todo momento.', 'Palavras-chave: menor parte/função isolada; sem banco, rede, navegador; base; rápido, barato, muitos. Nota cheia (0,4): definição + o que não usa + motivo da base. Metade (0,2): duas das três partes. Zero (0): confunde com E2E.'),
      (v_atividade, 1, 3, 'Explique o que é um teste de regressão e como ele teria evitado o problema do frete relatado pela equipe.', 0.4, 'Teste de regressão é o que **avisa quando uma alteração quebra algo que já funcionava**. Se existissem testes do cálculo do frete, ao alterar o carrinho a equipe rodaria a suíte (em segundos) e **o teste do frete falharia na hora**, antes da publicação, em vez de passar despercebido.', 'Palavras-chave: quebra o que funcionava; roda a cada alteração; falharia antes de publicar. Nota cheia (0,4): definição + aplicação ao caso do frete. Metade (0,2): só definição ou só aplicação. Zero (0): sem relação com regressão.'),
      (v_atividade, 2, 1, 'Diga qual ferramenta a UC usa para os testes unitários e por que ela foi escolhida para um projeto Vite/React.', 0.2, '**Vitest**, porque é **rápido**, **compatível com a sintaxe do Jest** e **já integrado a projetos Vite/React** (usa a mesma configuração do Vite).', 'Palavras-chave: Vitest; rápido; compatível com Jest; integrado ao Vite. Nota cheia (0,2): Vitest + pelo menos dois motivos. Metade (0,1): Vitest com um motivo. Zero (0): outra ferramenta.'),
      (v_atividade, 2, 2, 'Diga para que serve cada uma das ferramentas (Vitest, Jest, Testing Library, Cypress/Playwright) e em qual camada da pirâmide cada uma atua.', 0.4, '**Vitest:** executa testes JS/TS com asserções, mocks e cobertura — **unitário e integração**. **Jest:** alternativa com API quase igual — **unitário e integração**. **Testing Library:** testa componentes pelo que o usuário vê — **integração** (aula 4). **Cypress/Playwright:** controlam o navegador real — **E2E** (aula 6).', 'Palavras-chave: função e camada de cada ferramenta. Nota cheia (0,4): as quatro corretas. Metade (0,2): duas ou três corretas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 2, 3, 'Explique a relação entre Jest e Vitest e o que muda para a equipe que já conhece o Jest.', 0.4, 'O Jest é a **alternativa mais antiga, com API quase igual** à do Vitest (describe, it, expect, matchers). Quem conhece o Jest **aproveita quase tudo**: muda principalmente o import (vitest) e o mock (**vi.fn** no lugar de jest.fn).', 'Palavras-chave: mais antigo; API quase igual; reaproveita; vi.fn × jest.fn ou import. Nota cheia (0,4): relação + o que muda. Metade (0,2): só a relação. Zero (0): diz que são ferramentas sem relação ou que Jest é E2E.'),
      (v_atividade, 3, 1, 'Escreva o comando que cria o package.json e o comando que instala o Vitest como dependência de desenvolvimento.', 0.2, '**npm init -y** e **npm install -D vitest**.', 'Palavras-chave: npm init -y; npm install -D (ou --save-dev) vitest. Nota cheia (0,2): os dois comandos. Metade (0,1): um comando. Zero (0): nenhum correto.'),
      (v_atividade, 3, 2, 'Escreva os comandos que definem os scripts test e test:run no package.json e explique a diferença entre rodar npm test e npm run test:run.', 0.4, '**npm pkg set scripts.test="vitest" scripts.test:run="vitest run"** (aceitar também editar o package.json à mão com os dois scripts). **npm test** roda em **modo observação** (repete os testes a cada arquivo salvo); **npm run test:run** **roda uma vez e termina**.', 'Palavras-chave: scripts test = vitest e test:run = vitest run; observação × uma vez. Nota cheia (0,4): scripts + diferença. Metade (0,2): só scripts ou só diferença. Zero (0): diferença invertida.'),
      (v_atividade, 3, 3, 'Diga onde fica, por convenção, o arquivo de teste de src/utils/frete.js e explique qual dos dois modos (observação ou rodar uma vez) é usado no CI e por quê.', 0.4, 'O teste fica em **src/utils/frete.test.js** (ao lado do arquivo, com .test.js). No CI usa-se **npm run test:run** (rodar uma vez), porque o CI precisa que o comando **termine e devolva o resultado** (passou/falhou); o modo observação ficaria esperando para sempre.', 'Palavras-chave: frete.test.js; test:run/vitest run no CI; precisa terminar. Nota cheia (0,4): caminho + modo + motivo. Metade (0,2): dois dos três. Zero (0): modo observação no CI.'),
      (v_atividade, 4, 1, 'Diga o que significa cada A do padrão AAA.', 0.2, '**Arrange** = preparar os dados e o cenário; **Act** = executar o código testado; **Assert** = conferir o resultado com o esperado.', 'Palavras-chave: preparar; agir/executar; conferir. Nota cheia (0,2): os três. Metade (0,1): dois. Zero (0): um ou nenhum.'),
      (v_atividade, 4, 2, 'Indique qual linha do teste do colega é o Arrange, qual é o Act e qual é o Assert, explicando o papel de cada uma.', 0.4, '**Arrange:** const subtotal = 198.99 (prepara o dado de entrada). **Act:** const frete = calcularFrete(subtotal) (executa a função). **Assert:** expect(frete).toBe(19.9) (confere com o esperado).', 'Palavras-chave: cada linha na parte certa com o papel. Nota cheia (0,4): as três linhas certas com papel. Metade (0,2): linhas certas sem papel, ou duas certas. Zero (0): partes trocadas.'),
      (v_atividade, 4, 3, 'Escreva, no padrão AAA e com comentários marcando as três partes, um teste que confere o frete grátis com subtotal 250.', 0.4, 'it(''dá frete grátis com subtotal de 250'', () => { // Arrange: const subtotal = 250; // Act: const frete = calcularFrete(subtotal); // Assert: expect(frete).toBe(0); });', 'Palavras-chave: it/test; subtotal 250; calcularFrete; expect(...).toBe(0); comentários das três partes. Nota cheia (0,4): teste correto com resultado 0 e as três partes marcadas. Metade (0,2): teste correto sem marcar as partes, ou partes marcadas com resultado errado. Zero (0): resultado 19.9 ou sem expect.'),
      (v_atividade, 5, 1, 'Explique para que servem describe, it e expect.', 0.2, '**describe** agrupa os testes de uma unidade; **it** (ou test) é um caso de teste; **expect** recebe o valor obtido e, com o matcher, confere com o esperado.', 'Palavras-chave: agrupar; caso de teste; conferir. Nota cheia (0,2): os três. Metade (0,1): dois. Zero (0): um ou nenhum.'),
      (v_atividade, 5, 2, 'Escreva o arquivo de teste completo, com o import do Vitest e da função, um describe e três testes (frete pago, frete grátis e subtotal negativo).', 0.4, 'import { describe, it, expect } from ''vitest''; import { calcularFrete } from ''./frete.js''; describe(''calcularFrete'', () => { it(''cobra 19,90 abaixo de 199'', () => { expect(calcularFrete(198.99)).toBe(19.9); }); it(''dá frete grátis a partir de 199'', () => { expect(calcularFrete(199)).toBe(0); }); it(''recusa subtotal negativo'', () => { expect(() => calcularFrete(-1)).toThrow(''Subtotal inválido''); }); });', 'Palavras-chave: imports; describe; três it; toBe(19.9); toBe(0); toThrow com função. Nota cheia (0,4): arquivo completo com os três testes corretos. Metade (0,2): falta o import ou um dos testes, ou toThrow sem a função anônima. Zero (0): menos de dois testes corretos.'),
      (v_atividade, 5, 3, 'Explique como deve ser escrito o nome de cada teste e o que significa cada teste ser independente, dizendo o que aconteceria se um teste dependesse de outro.', 0.4, 'O nome descreve o **comportamento esperado** (como um caso de teste: "dá frete grátis a partir de 199"). Independente = **não depende da ordem nem do resultado de outro teste**. Se dependesse, **um teste falharia por causa de outro**, o resultado mudaria conforme a ordem e ficaria difícil achar a causa real (teste instável).', 'Palavras-chave: comportamento esperado; não depende da ordem/de outro; falha em cascata/instável. Nota cheia (0,4): nome + independência + consequência. Metade (0,2): dois dos três. Zero (0): diz que os testes devem depender uns dos outros.'),
      (v_atividade, 6, 1, 'Diga qual matcher usar em cada um dos cinco casos.', 0.2, '(1) **toBe**; (2) **toEqual**; (3) **toBeCloseTo**; (4) **toContain**; (5) **toThrow**.', 'Palavras-chave: os cinco matchers. Nota cheia (0,2): 5 ou 4 corretos. Metade (0,1): 2 ou 3. Zero (0): 0 ou 1.'),
      (v_atividade, 6, 2, 'Escreva a linha expect completa de cada um dos cinco casos.', 0.4, '(1) expect(total).toBe(10); (2) expect(item).toEqual({ id: 1, qtd: 2 }); (3) expect(0.1 + 0.2).toBeCloseTo(0.3); (4) expect(lista).toContain(''Teclado''); (5) expect(() => calcularFrete(-1)).toThrow().', 'Palavras-chave: cinco linhas completas e corretas. Nota cheia (0,4): 5 ou 4 corretas. Metade (0,2): 2 ou 3. Zero (0): 0 ou 1.'),
      (v_atividade, 6, 3, 'Explique por que expect(frete).toBe(0) é melhor que expect(frete).toBeFalsy() e por que o toThrow precisa receber uma função (() => calcularFrete(-1)).', 0.4, 'toBe(0) é **mais específico**: diz **exatamente o valor esperado**; toBeFalsy aceitaria também null, undefined, false ou "" e esconderia um defeito. O toThrow precisa de uma **função** porque o expect tem de **executar a chamada e capturar o erro**; se chamar calcularFrete(-1) direto, o erro estoura antes do expect e o teste quebra.', 'Palavras-chave: mais específico; toBeFalsy aceita outros valores; função para capturar o erro. Nota cheia (0,4): as duas explicações. Metade (0,2): uma explicação. Zero (0): nenhuma coerente.'),
      (v_atividade, 7, 1, 'Diga quantos caminhos a função calcularFrete tem e quais são.', 0.2, '**3 caminhos:** subtotal **negativo** (erro), subtotal **abaixo de 199** (19.9) e subtotal **a partir de 199** (0).', 'Palavras-chave: 3; negativo; abaixo de 199; a partir de 199. Nota cheia (0,2): número e os três caminhos. Metade (0,1): só o número ou dois caminhos. Zero (0): número errado sem caminhos.'),
      (v_atividade, 7, 2, 'Escreva os testes com os valores-limite 198.99, 199 e 199.01 e o resultado esperado de cada um.', 0.4, 'expect(calcularFrete(198.99)).toBe(19.9); expect(calcularFrete(199)).toBe(0); expect(calcularFrete(199.01)).toBe(0);', 'Palavras-chave: 198.99 → 19.9; 199 → 0; 199.01 → 0. Nota cheia (0,4): os três corretos. Metade (0,2): dois corretos. Zero (0): um ou nenhum.'),
      (v_atividade, 7, 3, 'Diga quantos testes, no mínimo, precisa uma função com um if/else dentro de outro if (sem else), e justifique contando os caminhos.', 0.4, '**3 testes:** (1) if de fora **falso**; (2) if de fora verdadeiro e if de dentro **verdadeiro**; (3) if de fora verdadeiro e if de dentro **falso** (else). São 3 caminhos possíveis, e cada caminho precisa de pelo menos um teste.', 'Palavras-chave: 3; os três caminhos; um teste por caminho. Nota cheia (0,4): número + caminhos justificados. Metade (0,2): número certo sem justificar, ou justificativa com 4 testes coerente. Zero (0): 1 ou 2 testes.'),
      (v_atividade, 8, 1, 'Explique o que significa o mutante ter "sobrevivido".', 0.2, 'O mutante "sobreviveu" porque **o código ficou errado e todos os testes continuaram passando**: a suíte **não detectou o defeito**.', 'Palavras-chave: código errado; testes passaram; não detectou. Nota cheia (0,2): ideia completa. Metade (0,1): só "os testes passaram". Zero (0): diz que é bom sinal.'),
      (v_atividade, 8, 2, 'Explique por que os testes com 50 e 500 não pegaram o mutante e qual valor revela o defeito.', 0.4, '50 e 500 estão **longe da borda**: com >= ou com >, 50 continua pagando e 500 continua grátis. Só o **valor-limite 199** muda: com >= é grátis (0) e com > passa a cobrar 19.9.', 'Palavras-chave: longe do limite; resultado igual com os dois operadores; 199 revela. Nota cheia (0,4): explicação + valor 199. Metade (0,2): só o valor 199 ou só a explicação. Zero (0): outro valor sem justificativa.'),
      (v_atividade, 8, 3, 'Escreva o teste que "mata" esse mutante e explique o que a dinâmica ensina sobre o valor de um teste.', 0.4, 'it(''dá frete grátis com subtotal exatamente 199'', () => { expect(calcularFrete(199)).toBe(0); }); — com o mutante, recebe 19.9 e **falha** (o mutante "morre"). A dinâmica ensina que **um teste só tem valor se falha quando o código está errado**.', 'Palavras-chave: teste com 199 esperando 0; falha com o mutante; teste só vale se falha com código errado. Nota cheia (0,4): teste + lição. Metade (0,2): só o teste ou só a lição. Zero (0): teste que não usa 199.'),
      (v_atividade, 9, 1, 'Explique o que é um mock e por que um teste unitário não deve chamar a API real.', 0.2, 'Mock é um **substituto controlado** de uma dependência, que **devolve o que o teste precisa e registra como foi chamado**. A API real deixaria o teste **lento, instável** (rede, servidor fora) e **deixaria de testar só a unidade**.', 'Palavras-chave: substituto controlado; registra chamadas; lento/instável; isolar a unidade. Nota cheia (0,2): definição + motivo. Metade (0,1): só um dos dois. Zero (0): mock = API real.'),
      (v_atividade, 9, 2, 'Escreva o teste do login aceito: crie o cliente falso com vi.fn().mockResolvedValue, chame entrar e confira o resultado e a chamada com toHaveBeenCalledWith.', 0.4, 'it(''devolve o token quando a API aceita'', async () => { const clienteFalso = vi.fn().mockResolvedValue({ ok: true, json: async () => ({ token: ''token-de-teste'' }) }); const resultado = await entrar(''teste@loja.local'', ''Senha123'', clienteFalso); expect(resultado).toEqual({ sucesso: true, token: ''token-de-teste'' }); expect(clienteFalso).toHaveBeenCalledWith(''/api/login'', expect.any(Object)); });', 'Palavras-chave: vi.fn().mockResolvedValue com ok true e json; await entrar com o mock; toEqual com sucesso e token; toHaveBeenCalledWith(''/api/login'', ...). Nota cheia (0,4): os quatro elementos. Metade (0,2): falta a conferência da chamada ou o await, ou o json do mock. Zero (0): usa fetch real ou sem mock.'),
      (v_atividade, 9, 3, 'Escreva o teste do login recusado (resposta com ok: false) e explique por que receber o cliente por parâmetro (injeção de dependência) facilita o teste e para que serve recriar os mocks no beforeEach.', 0.4, 'it(''indica falha quando a API recusa'', async () => { const clienteFalso = vi.fn().mockResolvedValue({ ok: false }); const resultado = await entrar(''teste@loja.local'', ''errada'', clienteFalso); expect(resultado.sucesso).toBe(false); }); Receber o cliente por parâmetro (**injeção de dependência**) deixa o teste **trocar o fetch real pelo mock**. Recriar os mocks no **beforeEach** dá **mocks novos antes de cada teste**, garantindo o **isolamento** (um teste não herda chamadas do outro).', 'Palavras-chave: mock com ok false; sucesso false; injeção = trocar pelo mock; beforeEach = isolamento. Nota cheia (0,4): teste + as duas explicações. Metade (0,2): teste sem explicações, ou explicações sem teste correto. Zero (0): nada coerente.'),
      (v_atividade, 10, 1, 'Explique por que escrever os testes antes de alterar o código.', 0.2, 'Os testes **mostram o defeito** (falham com o código atual) e depois **protegem a correção**: dá para alterar o código **sem medo de quebrar outros casos**, porque a suíte avisa.', 'Palavras-chave: mostram o defeito; protegem/regressão; corrigir com segurança. Nota cheia (0,2): as duas ideias. Metade (0,1): uma. Zero (0): sem justificativa.'),
      (v_atividade, 10, 2, 'Liste os cinco casos de teste da função (0%, 15%, 100%, percentual negativo e total com centavos), com a entrada e o resultado esperado de cada um.', 0.4, '**0%:** aplicarCupom(100, 0) → 100. **15%:** aplicarCupom(100, 15) → 85. **100%:** aplicarCupom(100, 100) → 0. **Negativo:** aplicarCupom(100, -10) → **lança erro**. **Centavos:** aplicarCupom(99.90, 15) → **84.915 (≈ 84,92)**, conferido com toBeCloseTo. (Aceitar outros totais com resultados coerentes.)', 'Palavras-chave: cinco casos com entrada e resultado; erro no negativo. Nota cheia (0,4): 5 ou 4 casos corretos. Metade (0,2): 2 ou 3. Zero (0): 0 ou 1.'),
      (v_atividade, 10, 3, 'Escreva o teste do total com centavos (ex.: total 99.90 com 15%) usando o matcher adequado e explique por que esse matcher é necessário.', 0.4, 'it(''aplica 15% em total com centavos'', () => { expect(aplicarCupom(99.90, 15)).toBeCloseTo(84.915); }); O **toBeCloseTo** é necessário porque **contas com casas decimais em JavaScript têm imprecisão** (ex.: 0.1 + 0.2 = 0.30000000000000004); o toBe compararia o valor exato e **falharia mesmo com a conta certa**.', 'Palavras-chave: toBeCloseTo; valor esperado coerente; imprecisão de ponto flutuante; toBe falharia. Nota cheia (0,4): teste + justificativa. Metade (0,2): teste sem justificativa, ou justificativa com teste usando toBe. Zero (0): sem teste nem justificativa.');
end $$;
